analyze.mjs.text:
// Classifies one HTTP response's Set-Cookie headers (real headers collected
// by probe.mjs's live network request, or pasted in by hand) into named
// cookie-security misconfiguration patterns.
//
// Pure function, no I/O, no network -- this is the module both the CLI
// (check.mjs, which fetches for real) and the browser page (index.html,
// which can only ever analyse a payload someone already fetched) import, so
// the classification logic exists exactly once.
//
// The value here isn't reading three attribute names -- curl -I does that.
// It's two things a naive implementation gets wrong:
//
//   * Set-Cookie cannot be joined into one string and re-split on commas the
//     way most other response headers can. An Expires attribute contains a
//     comma of its own ("Expires=Wed, 21 Oct 2026 07:28:00 GMT"), so
//     `headers['set-cookie'].join(', ').split(',')` silently corrupts every
//     cookie that carries one. Node's http/https clients already split
//     multiple Set-Cookie headers into a proper array before your code ever
//     sees it -- probe.mjs reads that array directly and this module takes
//     it as already-correct input, never re-joining or re-splitting it.
//   * SameSite=None without Secure and a __Host-/__Secure- prefix violation
//     are not merely weaker protection -- Chrome, Firefox, and Safari all
//     reject the Set-Cookie header outright in those cases (see the two
//     "danger" findings below). A response can look like it configured a
//     cookie and have the browser silently refuse to store it at all, which
//     reads as a functional bug (the user gets logged out, a flow breaks)
//     as often as a security one.

/** Splits one raw Set-Cookie header value into { name, value, attrs }. attrs
 * keys are lowercased; a flag attribute (Secure, HttpOnly) maps to `true`;
 * a valued attribute (SameSite, Domain, Path, Expires, Max-Age) maps to its
 * raw string value. */
export function parseSetCookieHeader(raw) {
  const parts = String(raw).split(';').map((p) => p.trim());
  const [nameValue, ...attrParts] = parts;
  const eq = nameValue.indexOf('=');
  const name = eq === -1 ? nameValue : nameValue.slice(0, eq).trim();
  const value = eq === -1 ? '' : nameValue.slice(eq + 1).trim();
  const attrs = {};
  for (const part of attrParts) {
    if (!part) continue;
    const attrEq = part.indexOf('=');
    if (attrEq === -1) {
      attrs[part.toLowerCase()] = true;
    } else {
      attrs[part.slice(0, attrEq).trim().toLowerCase()] = part.slice(attrEq + 1).trim();
    }
  }
  return { name, value, attrs };
}

function findingsForCookie(cookie, { isHttps }) {
  const findings = [];
  const { name, attrs } = cookie;
  const secure = attrs.secure === true;
  const httpOnly = attrs.httponly === true;
  const sameSite = typeof attrs.samesite === 'string' ? attrs.samesite.toLowerCase() : null;
  const evidence = `set-cookie: ${name}=...${Object.keys(attrs).length ? '; ' + Object.keys(attrs).join('; ') : ''}`;

  let prefixDangerFired = false;

  if (name.startsWith('__Host-')) {
    const violations = [];
    if (!secure) violations.push('no Secure attribute');
    if (attrs.domain !== undefined) violations.push('carries a Domain attribute');
    if (attrs.path !== '/') violations.push(attrs.path ? `Path is "${attrs.path}", not "/"` : 'no Path=/ attribute');
    if (violations.length > 0) {
      prefixDangerFired = true;
      findings.push({
        id: 'host-prefix-violated',
        severity: 'danger',
        title: `"${name}" uses the __Host- prefix but violates its rules`,
        detail:
          `A cookie named __Host-... is a browser-enforced contract: Secure must be set, no Domain ` +
          `attribute may be present, and Path must be exactly "/". This response violates it (${violations.join('; ')}), ` +
          'so a compliant browser silently refuses to store the cookie at all rather than storing a weaker version of it -- ' +
          'the response looks like it set a cookie and no cookie is actually stored.',
        evidenceHeader: evidence,
      });
    }
  } else if (name.startsWith('__Secure-')) {
    if (!secure) {
      prefixDangerFired = true;
      findings.push({
        id: 'secure-prefix-violated',
        severity: 'danger',
        title: `"${name}" uses the __Secure- prefix but has no Secure attribute`,
        detail:
          'A cookie named __Secure-... is a browser-enforced contract requiring the Secure attribute. ' +
          'This response omits it, so a compliant browser silently refuses to store the cookie at all -- ' +
          'the response looks like it set a cookie and no cookie is actually stored.',
        evidenceHeader: evidence,
      });
    }
  }

  if (sameSite === 'none' && !secure) {
    findings.push({
      id: 'samesite-none-without-secure',
      severity: 'danger',
      title: `"${name}" is SameSite=None without Secure`,
      detail:
        'SameSite=None declares that this cookie should be sent on cross-site requests, which requires ' +
        'the Secure attribute per the current SameSite specification. Chrome, Firefox, and Safari all reject ' +
        'a SameSite=None cookie outright when Secure is missing, rather than merely restricting it to same-site ' +
        'requests -- so this is not a weaker cookie, it is one that fails to be set in any current browser.',
      evidenceHeader: evidence,
    });
  }

  if (isHttps && !secure && !prefixDangerFired) {
    findings.push({
      id: 'missing-secure',
      severity: 'notice',
      title: `"${name}" has no Secure attribute`,
      detail:
        'This response was served over HTTPS but the cookie has no Secure attribute, so a browser will still ' +
        "attach it to a future plain-HTTP request to the same host (or a subdomain, if Domain is set broadly) -- " +
        'exposing it to anyone who can observe that unencrypted connection.',
      evidenceHeader: evidence,
    });
  }

  if (!httpOnly) {
    findings.push({
      id: 'missing-httponly',
      severity: 'notice',
      title: `"${name}" has no HttpOnly attribute`,
      detail:
        "Without HttpOnly, this cookie's value is readable by JavaScript running on the page (document.cookie), " +
        'so any script-injection (XSS) bug on the site can read and exfiltrate it. Not every cookie needs this -- ' +
        "a UI preference a script legitimately needs to read is a reasonable exception -- but a session or " +
        'authentication cookie without it turns any XSS into session theft.',
      evidenceHeader: evidence,
    });
  }

  if (sameSite === null) {
    findings.push({
      id: 'missing-samesite',
      severity: 'notice',
      title: `"${name}" has no SameSite attribute`,
      detail:
        'With no SameSite attribute, current versions of Chrome, Firefox, and Edge default the cookie to ' +
        'SameSite=Lax, but older or less common browsers may still default to sending it on every cross-site ' +
        'request -- setting the attribute explicitly (Lax, Strict, or None with Secure) removes that ambiguity ' +
        'rather than relying on a default that varies by browser.',
      evidenceHeader: evidence,
    });
  }

  return findings;
}

function norm(value) {
  return typeof value === 'string' ? value.trim() : null;
}

/**
 * @param {string} target - the URL that was probed (for display only)
 * @param {{ok: boolean, status: number|null, protocol: string|null,
 *   setCookie: string[], error: string|null}} probe
 * @returns {{target: string, probe: object, cookies: object[], findings: object[],
 *   dangerCount: number, noticeCount: number, ok: boolean, incomplete: boolean}}
 */
export function buildReport(target, probe) {
  const p = probe && typeof probe === 'object' ? probe : { ok: false };
  const incomplete = p.ok === false;
  const rawCookies = Array.isArray(p.setCookie) ? p.setCookie : [];
  const isHttps = p.protocol === 'https:';

  let cookies = [];
  let findings = [];

  if (!incomplete) {
    cookies = rawCookies.map(parseSetCookieHeader);
    for (const cookie of cookies) {
      findings = findings.concat(findingsForCookie(cookie, { isHttps }));
    }
  }

  const dangerCount = findings.filter((f) => f.severity === 'danger').length;
  const noticeCount = findings.filter((f) => f.severity === 'notice').length;

  return {
    target,
    probe: {
      ok: p.ok !== false,
      status: p.status ?? null,
      protocol: p.protocol ?? null,
      setCookie: rawCookies,
      error: norm(p.error),
    },
    cookies: cookies.map((c) => ({ name: c.name, attrs: c.attrs })),
    findings,
    dangerCount,
    noticeCount,
    ok: !incomplete && dangerCount === 0,
    incomplete,
  };
}

check.mjs.text:
#!/usr/bin/env node
// CLI: sends one real GET request to a URL you name and reports which
// cookie-security misconfiguration patterns the response's Set-Cookie
// headers show. Your machine, your network -- no request goes through this
// portfolio or anywhere but the URL you pass.
//
//   node check.mjs <url> [--json] [--timeout <ms>]
//
// Only point this at a system you own or are authorised to test. This
// sends one ordinary, unauthenticated GET request -- nothing here bypasses
// authentication, reads protected data, or does anything a browser
// wouldn't also do by visiting the URL -- but treat it the same as you
// would curl or any other request tool aimed at someone else's server.
//
// Exit code 0 when the probe completed and no "danger"-severity finding is
// present; 1 when a danger finding is present or the probe failed to
// complete (network error, timeout, bad URL).

import { runProbe } from './probe.mjs';
import { buildReport } from './analyze.mjs';

function formatText(report) {
  const lines = [];
  lines.push(`Target: ${report.target}`);
  if (!report.probe.ok) {
    lines.push(`Request failed: ${report.probe.error}`);
    lines.push('');
    lines.push('The probe did not complete -- re-run once the target is reachable.');
    return lines.join('\n');
  }
  lines.push(`Status: ${report.probe.status}  (${report.probe.protocol ?? 'unknown scheme'})`);
  lines.push('');

  if (report.probe.setCookie.length === 0) {
    lines.push('No Set-Cookie header on this response -- nothing to check.');
  } else {
    lines.push(`${report.probe.setCookie.length} cookie(s) set on this response:`);
    for (const raw of report.probe.setCookie) lines.push(`  ${raw}`);
  }
  lines.push('');

  if (report.findings.length === 0) {
    lines.push('None of the patterns this tool checks for were found.');
  } else {
    for (const f of report.findings) {
      const mark = f.severity === 'danger' ? '!!' : '--';
      lines.push(`${mark} [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`     ${f.detail}`);
      lines.push(`     evidence: ${f.evidenceHeader}`);
      lines.push('');
    }
  }

  lines.push(
    'This is evidence from this one response, not a full security assessment -- ' +
      'see README.md for what this tool does and does not check.',
  );
  return lines.join('\n');
}

function parseArgs(argv) {
  const args = { target: null, json: false, timeoutMs: undefined };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--json') args.json = true;
    else if (argv[i] === '--timeout') args.timeoutMs = Number(argv[++i]);
    else if (!args.target && !argv[i].startsWith('--')) args.target = argv[i];
  }
  return args;
}

/** Pure orchestration: given a probe function (real network, or a stub in
 * tests), fetch and classify. Kept separate from main() so tests can inject
 * a fake `probeFn` instead of hitting the network. */
export async function runCheck(target, { probeFn = runProbe, timeoutMs } = {}) {
  const probe = await probeFn(target, timeoutMs ? { timeoutMs } : {});
  return buildReport(target, probe);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.target) {
    console.error('Usage: node check.mjs <url> [--json] [--timeout <ms>]');
    process.exit(2);
  }
  try {
    // eslint-disable-next-line no-new
    new URL(args.target);
  } catch {
    console.error(`Not a valid URL: ${args.target}`);
    process.exit(2);
  }

  const report = await runCheck(args.target, { timeoutMs: args.timeoutMs });

  if (args.json) {
    console.log(JSON.stringify({ target: report.target, probe: report.probe }, null, 2));
  } else {
    console.log(formatText(report));
  }
  process.exit(report.ok ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

probe.mjs.text:
// Sends the one real HTTP request this check depends on: a GET to the
// target URL, reading back the response's Set-Cookie headers. Node's
// built-in http/https clients are used, and no redirect is followed
// automatically -- a 3xx response is reported as-is, with its own cookies,
// rather than silently chasing the Location so a caller always knows
// exactly which response the report describes.
//
// This module only ever talks to the one target URL a caller names. It
// makes no other network call, reads no local files, and sends nothing
// anywhere else.
//
// Node's http/https response object already exposes `set-cookie` as an
// array of the individual raw header values -- one entry per Set-Cookie
// header the server sent -- rather than folding them into one
// comma-joined string the way it does for every other repeated header.
// That is preserved here unchanged: joining it and re-splitting on commas
// would corrupt any cookie carrying an Expires attribute, since
// "Expires=Wed, 21 Oct 2026 07:28:00 GMT" contains a comma of its own.

import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';

const DEFAULT_TIMEOUT_MS = 10_000;
const USER_AGENT =
  'cookie-security-check/1 (+https://duncan-haywood.github.io/monorepo-projects/cookie-security-check/)';

/**
 * One GET request to `targetUrl`. Resolves rather than rejects on any
 * failure so a caller never needs a try/catch around it.
 */
export function sendProbe(targetUrl, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  return new Promise((resolve) => {
    let parsed;
    try {
      parsed = new URL(targetUrl);
    } catch (err) {
      resolve({ ok: false, status: null, protocol: null, setCookie: [], error: `invalid URL: ${err.message}` });
      return;
    }
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      resolve({ ok: false, status: null, protocol: null, setCookie: [], error: `unsupported scheme: ${parsed.protocol}` });
      return;
    }

    const requester = parsed.protocol === 'https:' ? httpsRequest : httpRequest;
    const headers = { 'user-agent': USER_AGENT, accept: 'text/html,*/*' };

    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    const req = requester(
      parsed,
      { method: 'GET', headers, timeout: timeoutMs },
      (res) => {
        res.on('data', () => {}); // headers are all this check needs; drain and discard the body
        res.on('end', () => {
          const setCookie = Array.isArray(res.headers['set-cookie']) ? res.headers['set-cookie'] : [];
          finish({
            ok: true,
            status: res.statusCode ?? null,
            protocol: parsed.protocol,
            setCookie,
            error: null,
          });
        });
        res.on('error', (err) => finish({ ok: false, status: res.statusCode ?? null, protocol: parsed.protocol, setCookie: [], error: err.message }));
      },
    );
    req.on('timeout', () => req.destroy(new Error('timed out')));
    req.on('error', (err) => finish({ ok: false, status: null, protocol: parsed.protocol, setCookie: [], error: err.message }));
    req.end();
  });
}

/** Runs the single probe against `targetUrl` and returns the raw result
 * (same shape `analyze.mjs`'s `buildReport` expects). */
export async function runProbe(targetUrl, opts = {}) {
  return { target: targetUrl, ...(await sendProbe(targetUrl, opts)) };
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores the
// target URL, the pasted probe JSON, or anything about what was checked --
// that is exactly the kind of thing that must not be transmitted anywhere,
// and this tool never reads it off the visitor's machine either.

const STORAGE_KEY = 'cookie-security-check-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'check_run') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters:
// opting out *removes* the counters, so a flag stored inside them would
// be deleted by the very act it records. `recordUsage` above consults it
// directly as well as taking the caller's argument -- a stored preference
// that only one line of page wiring reads is one line away from being
// forgotten, which is the defect this change exists to fix.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem
  // that throws on a full quota skips the delete entirely, and the
  // visitor gets neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
